before.content:
  handshake.destroy()
  channel?.destroy()
  if (socket.readyState === WebSocket.OPEN || socket.readyState === WebSocket.CONNECTING) {
    socket.close(1008, "Relay channel rejected")
  }
  callbacks.failed(failure instanceof Error ? failure : new Error(String(failure)))
}

